// ChangeCount is the resolver for the changeCount field.
func (r *mutationResolver) ChangeCount(ctx context.Context, input model.UserSongCountInput) (int, error) {
	songModel := &model.Songs{}
	result := r.DB.Where("user_id=? AND song_id=?", input.UserID, input.SongID).First(songModel)
	if result.Error != nil {
		if errors.Is(result.Error, gorm.ErrRecordNotFound) {
			return 0, fmt.Errorf("song not found for user")
		}
		return 0, fmt.Errorf("database query failed: %s", result.Error.Error())
	}
	currentCount := songModel.PlayCount
	songModel.PlayCount = currentCount + 1
	err := r.DB.Save(songModel).Error
	if err != nil {
		return 0, fmt.Errorf("failed to update play count: %s", err.Error())
	}
	return songModel.ID, nil
}

