// PredictSong is the resolver for the predictSong field.
func (r *queryResolver) PredictSong(ctx context.Context, query model.SongInput) (*model.PredictOutput, error) {
	rows, err := r.DB.Model(&model.Songs{}).Select("user_id, song_id, play_count").Rows()
	if err != nil {
		errMsg := err.Error()
		return &model.PredictOutput{
			Success: false,
			Errors:  []*string{&errMsg},
			Data:    nil,
		}, nil
	}
	defer rows.Close()
	var dataset []ai_functions.SongRating
	for rows.Next() {
		var sr ai_functions.SongRating
		var rowPlayCount float64
		if err := rows.Scan(&sr.UserID, &sr.SongID, &rowPlayCount); err != nil {
			errMsg := err.Error()
			errMsgPtr := errMsg
			return &model.PredictOutput{Success: false, Errors: []*string{&errMsgPtr}, Data: nil}, nil
		}
		sr.Score = math.Min(rowPlayCount, 5.0)
		dataset = append(dataset, sr)
	}
	predictions, err := ai_functions.GetRecommendations(dataset, query.UserID.String(), 3)
	if err != nil {
		errMsg := err.Error()
		errMsgPtr := errMsg
		return &model.PredictOutput{Success: false, Errors: []*string{&errMsgPtr}, Data: nil}, nil
	}
	var gqlPredictions []*model.Prediction
	for _, p := range predictions {
		common := p.Common
		score := p.Score
		id := p.ID

		gqlPredictions = append(gqlPredictions, &model.Prediction{
			ID:     &id,
			Score:  &score,
			Common: &common,
		})
	}
	return &model.PredictOutput{
		Success: true,
		Errors:  []*string{},
		Data:    gqlPredictions,
	}, nil
}
